import { useLayoutEffect, useState, useRef } from 'react';
import { useAIAssistance } from '../context/AIAssistanceContext';

/**
 * Custom Investment Robot Cursor - friendly mascot with ₨ PKR on chest
 * Replaces default cursor, follows mouse, animates on hover/click
 */
export default function RobotCursor() {
  const { enabled: aiAssistanceOn } = useAIAssistance();
  const [pos, setPos] = useState({ x: -100, y: -100 });
  const [hover, setHover] = useState(false);
  const [click, setClick] = useState(false);
  const rafRef = useRef(null);
  const targetRef = useRef({ x: -100, y: -100 });

  useLayoutEffect(() => {
    if (aiAssistanceOn) {
      document.documentElement.classList.remove('df-robot-cursor');
      return undefined;
    }

    document.documentElement.classList.add('df-robot-cursor');

    const handleMove = (e) => {
      targetRef.current = { x: e.clientX, y: e.clientY };
      if (!rafRef.current) {
        rafRef.current = requestAnimationFrame(animate);
      }
    };

    const animate = () => {
      const t = targetRef.current;
      setPos(p => ({
        x: p.x + (t.x - p.x) * 0.15,
        y: p.y + (t.y - p.y) * 0.15,
      }));
      rafRef.current = requestAnimationFrame(animate);
    };

    const handleOver = (e) => {
      const el = e.target;
      const clickable = el.closest('a, button, [role="button"], input, select, textarea, [onclick]');
      setHover(!!clickable);
    };

    const handleDown = () => setClick(true);
    const handleUp = () => setTimeout(() => setClick(false), 150);

    window.addEventListener('mousemove', handleMove);
    document.addEventListener('mouseover', handleOver);
    document.addEventListener('mousedown', handleDown);
    document.addEventListener('mouseup', handleUp);

    return () => {
      document.documentElement.classList.remove('df-robot-cursor');
      window.removeEventListener('mousemove', handleMove);
      document.removeEventListener('mouseover', handleOver);
      document.removeEventListener('mousedown', handleDown);
      document.removeEventListener('mouseup', handleUp);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    };
  }, [aiAssistanceOn]);

  if (aiAssistanceOn) {
    return null;
  }

  return (
    <>
      <div
        className="fixed pointer-events-none z-[9999] transition-transform duration-75"
        style={{
          left: pos.x,
          top: pos.y,
          transform: `translate(-50%, -50%) scale(${hover ? 1.15 : 1})`,
        }}
      >
        <div
          className={`w-8 h-8 transition-all duration-150 ${
            click ? 'scale-90' : 'scale-100'
          } ${click ? 'shadow-[0_0_20px_rgba(34,197,94,0.8)]' : hover ? 'shadow-[0_0_20px_rgba(45,212,191,0.5)]' : ''}`}
        >
          <svg viewBox="0 0 64 64" width="32" height="32" className="w-8 h-8 overflow-visible">
            {/* Robot body */}
            <rect x="12" y="20" width="40" height="36" rx="6" fill={click ? '#22c55e' : '#0a0e14'} stroke="#5eb8e8" strokeWidth="2" />
            {/* PKR symbol on chest */}
            <text x="32" y="42" textAnchor="middle" fill="white" fontSize="14" fontWeight="bold" fontFamily="system-ui">₨</text>
            {/* Head */}
            <rect x="18" y="8" width="28" height="16" rx="4" fill="#141c28" stroke="#5eb8e8" strokeWidth="1.5" />
            {/* Eyes */}
            <circle cx="24" cy="16" r="2.5" fill="white" className={hover ? 'animate-pulse' : ''} />
            <circle cx="40" cy="16" r="2.5" fill="white" className={hover ? 'animate-pulse' : ''} />
            {/* Antenna */}
            <line x1="32" y1="8" x2="32" y2="2" stroke="#5eb8e8" strokeWidth="1.5" />
            <circle cx="32" cy="2" r="2" fill="#5eb8e8" />
          </svg>
        </div>
      </div>
    </>
  );
}
